# Flink configuration generated by the launcher, identical for every YT job of the operation. It replaces
# the distribution's config.yaml; only per-container addresses stay on the command line (application mode).
mkdir -p "$FLINK_CONF_DIR"
# Flink >= 1.19 falls back to the legacy flink-conf.yaml when it exists, which would hide config.yaml.
rm -f "$FLINK_CONF_DIR/flink-conf.yaml"
cat > "$FLINK_CONF_DIR/config.yaml" <<'FLYT_FLINK_CONF_EOF'
{flink_conf_yaml}
FLYT_FLINK_CONF_EOF
echo "Flink configuration ($FLINK_CONF_DIR/config.yaml):" 1>&2
cat "$FLINK_CONF_DIR/config.yaml" 1>&2
